INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (81, 14847, 'gateway-route.json', 'GATEWAY_GROUP', '', '[ {\n  \"id\" : \"iwindplus-mgt\",\n  \"uri\" : \"lb://iwindplus-mgt\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/mgt/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"管理服务\"\n  },\n  \"order\" : \"1\"\n}, {\n  \"id\" : \"iwindplus-log\",\n  \"uri\" : \"lb://iwindplus-log\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/log/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"日志服务\"\n  },\n  \"order\" : \"2\"\n}, {\n  \"id\" : \"iwindplus-auth\",\n  \"uri\" : \"lb://iwindplus-auth\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/api/auth/**\"\n    }\n  } ],\n  \"filters\" : [ {\n    \"name\" : \"StripPrefix\",\n    \"args\" : {\n      \"parts\" : \"2\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"认证服务\"\n  },\n  \"order\" : \"3\"\n}, {\n  \"id\" : \"iwindplus-im\",\n  \"uri\" : \"lb://iwindplus-im\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/im/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"即时通讯服务\"\n  },\n  \"order\" : \"4\"\n}, {\n  \"id\" : \"iwindplus-im-ws\",\n  \"uri\" : \"lb:ws://iwindplus-im-ws\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/imWs/**\"\n    }\n  } ],\n  \"filters\" : [ {\n    \"name\" : \"StripPrefix\",\n    \"args\" : {\n      \"parts\" : \"2\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"即时通讯websocket服务\"\n  },\n  \"order\" : \"5\"\n}, {\n  \"id\" : \"iwindplus-setup\",\n  \"uri\" : \"lb://iwindplus-setup\",\n  \"predicates\" : [ {\n    \"n