notEmpty=详细地址必填\ndistrict.notEmpty=区县必填\nfriendId.notEmpty=好友ID必填\njoinType.notEmpty=加入类型必填\nmoduleDesc.notEmpty=模块描述必填\nmoduleName.notEmpty=模块名称必填\noperateDesc.notEmpty=操作描述必填\noperateName.notEmpty=操作名称必填\noperateType.notEmpty=操作类型必填\nphoneNumbers.notEmpty=电话号码必填\nprefix.notEmpty=前缀必填\nprovince.notEmpty=省份必填\nreceiverId.notEmpty=接收者ID必填\nrequestMethod.notEmpty=请求方法必填\nrequestPath.notEmpty=请求路径必填\nresourceId.notEmpty=资源ID必填\nsenderId.notEmpty=发送者ID必填\nsmsType.notEmpty=短信类型必填\nsmtpNickName.notEmpty=SMTP昵称必填\nsmtpPort.notEmpty=SMTP端口必填\nsmtpRetryEnable.notEmpty=SMTP重试启用必填\nsmtpSslEnable.notEmpty=SMTP SSL启用必填\nsourceFileName.notEmpty=源文件名必填\nsystemId.notEmpty=系统ID必填\ntable.notEmpty=表必填\ntargetServer.notEmpty=目标服务器必填\ntemplateContent.notEmpty=模板内容必填\ntemplateName.notEmpty=模板名称必填\ntplCode.notEmpty=模板代码必填\nvodType.notEmpty=视频类型必填\ni18n_msg_value_too_long=国际化消息集合中含有长度超过100的值', '4a983d5342fd04ad20393bcd464d80e7', '2026-08-03 00:13:45', '2026-08-03 00:13:45', NULL, '172.20.10.11', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"properties\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (45, 15187, 'iwindplus-binlog-producer-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9008\n  shutdown: graceful\n  servlet:\n    application-display-name: binlog生产者\n    encoding:\n      force: true\n      force-request: true\n      force-response: true\n  undertow:\n    threads:\n      io: 16\n      worker: 256\n    buffer-size: 1024\n    direct-buffers: true\ncross:\n  # 是否开启跨域\n  enabled: false\nfilter:\n  xss:\n    # 是否开启xss过滤器，防止攻击\n    enabled: true\n  request:\n    # 是否开启请求过滤器\n    enabled: true\n  # 过滤器加解密使用\n  crypto:\n    # 算法\n    algorithm: AES\n    # 公钥\n    # publicKey:\n    # 私钥\n    # privateKey:\n    # 密钥\n    # key:\n    # 初始化向量\n    # iv:\nhttp:\n  client:\n    api-protection:\n      # 是否开启API防护\n      enabled: true\n      enabled-remote: false\n      access-key: 555cb03355e1da059debe72b3e318c2c\n      secret-key: cd2o99YOb7hvx7enMk05YzmUSRXusGer\nglobal:\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\nresponse:\n  body:\n    enabled: true\n    crypto:\n      # 是否开启加密功能，默认关闭\n      enabled: false\n      # 算法\n      algorithm: RSA\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\njackson:\n  # 是否开启自定义jackson配置\n  enabled: true\n  sensitive:\n    # 是否开启敏感数据脱敏，响应接口结果时用\n    enabled: false\nvalidator:\n  # 是否开启参数校验\n  enabled: true\n  # 是否快速失败返回模式\n  fail-fast: true\nkey:\n  generator:\n    # 是否开启唯一key\n    enabled: true\n    # key是否开启加密\n    enabled-crypto: true\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nswagger:\n  server-api:\n    # 是否启用API注册\n    enabled: true\n    # 最大重试次数\n    maxRetry: 5\n    # 重试间隔时间（单位：秒）\n    retryInterval: 3\nfeign:\n  request:\n    # 是否开启请求拦截器，传递请求头信息\n    enabled: true\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\n  sentinel:\n    enabled: true\nloadbalancer:\n  nacos:\n    # 是否开启nacos负载均衡，请求头设置version，支持灰度\n    enabled: true\n  custom:\n    # 是否开启自定义负载均衡，请求头设置version，支持灰度\n    enabled: false\n# 全局默认熔断策略\nresilience4j:\n  circuitbreaker:\n    configs:\n      default:\n        # 失败率阈值，达到50%触发熔断\n        failureRateThreshold: 50\n        # 慢调用率阈值\n        slowCallRateThreshold: 80\n        # 慢调用时间阈值（毫秒）\n        slowCallDurationThreshold: 1000\n        # 熔断器开启持续时间（秒）\n        waitDurationInOpenState: 10s\n        # 允许半开状态的最大调用数\n        permittedNumberOfCallsInHalfOpenState: 3\n        # 滑动窗口大小\n        slidingWindowSize: 10\n        # 最小调用次数才计算失败率\n        minimumNumberOfCalls: 5\n        # 自动从打开状态过渡到半开状态\n        automaticTransitionFromOpenToHalfOpenEnabled: true\n        # 仅以下异常计入失败\n        record-exceptions:\n          - java.io.IOException\n          - java.util.concurrent.TimeoutException\n    # 留空即可，全部走 default\n    instances: {}\n  timelimiter:\n    configs:\n      default:\n        # 单次调用硬超时 3 s（覆盖 Feign 默认 1 s）\n        timeout-duration: 3s\n  # 重试配置（可选）\n  retry:\n    configs:\n      default:\n        # 含首次，共 3 次\n        max-attempts: 3\n        wait-duration: 500ms\n        enable-exponential-backoff: true\n        exponential-backoff-multiplier: 1.5\n  # 限流配置（可选）\n  ratelimiter:\n    configs:\n      default:\n        limit-for-period: 10\n        limit-refresh-period: 1s\n        timeout-duration: 1000\n  # 隔离配置（可选）\n  bulkhead:\n    configs:\n      default:\n        maxConcurrentCalls: 10\n        maxWaitDuration: 0\ndynamictp:\n  enabled: true\n  enabledCollect: true\n  enabledBanner: true\n  collectorTypes: micrometer\n  monitorInterval: 5\n  platforms:\n    - platform: lark\n      platformId: 1\n      urlKey: e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n      receivers: test1,test2\n  globalExecutorProps:\n    rejectedHandlerType: CallerRunsPolicy\n    queueType: VariableLinkedBlockingQueue\n    waitForTasksToCompleteOnShutdown: true\n    awaitTerminationSeconds: 3\n    taskWrapperNames: [ \"micrometer\", \"ttl\", \"mdc\" ]\n    queueTimeout: 300\n    runTimeout: 300\n    notifyEnabled: true\n    notifyItems:\n      - type: change\n        silencePeriod: 120\n      - type: capacity\n        threshold: 80\n        count: 2\n        period: 30\n        silencePeriod: 0\n      - type: liveness\n        threshold: 80\n        count: 3\n        period: 30\n        silencePeriod: 0\n      - type: reject\n        count: 1\n        period: 30\n        silencePeriod: 0\n      - type: run_timeout\n        count: 20\n        period: 30\n        silencePeriod: 30\n      - type: queue_timeout\n        count: 5\n        period: 30\n        silencePeriod: 0\n  executors:\n    - threadPoolName: asyncTaskExecutor\n      threadPoolAliasName: 异步任务线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: asyncTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nTaskExecutor\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      threadNamePrefix: i18nTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientTaskExecutor\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: httpClientTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: binlogTaskExecutor\n      threadPoolAliasName: binlog线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: binlogTask\n      runTimeout: 0\n      platformIds: [ 1 ]\n      preStartAllCoreThreads: true\n    - threadPoolName: binlogTaskScheduler\n      threadPoolAliasName: binlog调度线程池\n      executorType: scheduled\n      corePoolSize: 5\n      maximumPoolSize: 10\n      threadNamePrefix: binlogScheduler\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerTaskExecutor\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: kafkaListerTask\n      runTimeout: 0\n      queueTimeout: 0\n      platformIds: [ 1 ]\nspring:\n  cloud:\n    circuitbreaker:\n      resilience4j:\n        enabled: true\n    openfeign:\n      circuitbreaker:\n        # 开启服务熔断\n        enabled: true\n        group:\n          enabled: true\n      micrometer:\n        enabled: true\n      compression:\n        request:\n          enabled: false\n        response:\n          enabled: false\n      httpclient:\n        hc5:\n          enabled: true\n          connection-request-timeout: 3\n          socket-timeout: 10\n          pool-reuse-policy: fifo\n          pool-concurrency-policy: STRICT\n        # 默认连接超时时间：2000毫秒\n        connection-timeout: 5000\n        # 连接池管理定时器执行频率：默认 3000（单位：毫秒）\n        connection-timer-repeat: 5000\n        # 连接池最大连接数，默认200\n        max-connections: 500\n        # 每一个IP最大占用多少连接 默认 50\n        max-connections-per-route: 200\n        # 连接池中存活时间，默认为5\n        time-to-live: 10\n        time-to-live-unit: minutes\n        ok-http:\n          read-timeout: 10000\n      client:\n        config:\n          # default代表所有服务\n          default:\n            # 日志级别\n            loggerLevel: FULL\n            # feign客户端建立连接超时时间（单位：毫秒）\n            connect-timeout: 5000\n            # feign客户端建立连接后读取资源超时时间（单位：毫秒）\n            read-timeout: 10000\n      okhttp:\n        enabled: false\n  mvc:\n    path-match:\n      matching-strategy: ant_path_matcher\n  jmx:\n    enabled: true\n  messages:\n    basename: i18n/messages\n    fallback-to-system-locale: true\n    cache-duration: -1\n    # 是否开启远程消息源\n    enabled-remote: true\n    # nacos分组名称\n    group: I18N_GROUP\n  servlet:\n    multipart:\n      enabled: true\n      maxFileSize: 1GB\n      maxRequestSize: 10GB\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: false\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          enable-reactive: true\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerTaskExecutor\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-binlog-topic\n            group: iwindplus-binlog-group\n            # 是否自动创建\n            auto-create: true\nbinlog:\n  # 是否开启binlog\n  enabled: true\n  # topic前缀（发送数据）\n  topic-prefix: iwindplus-binlog-topic\n  data-sources:\n    - type: mysql\n      server-id: 1\n      host: 127.0.0.1\n      port: 3317\n      username: root\n      password: njX@D*4ETsm3\n      # 包含的数据库\n      database-include-list: iwindplus-mgt\n      # 排除的数据库\n      database-exclude-list:\n      # 包含的表\n      table-include-list: iwindplus-mgt.user\n      # 排除的的表\n      table-exclude-list:\n  # binlog 消费位点\n  offset:\n    topic: ${binlog.topic-prefix}-offset\n    replication-factor: -1\n    num-partitions: -1\n  # 同步表结构变化历史\n  history:\n    topic: ${binlog.topic-prefix}-schema-history\n    replication-factor: -1\n    num-partitions: -1\nlogging:\n  level:\n    root: INFO\n  console:\n    enabled: true\n    enabled-async: true\n  logstash:\n    enabled: true\n    enabled-async: true\n    address: 127.0.0.1:4560\n  config: classpath:logback-spring.xml\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: 8W9QPBbekJdpE1mCdqRmkfyD5rJGqxiw\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n    stack:\n      max-length: -1\n      max-frames: -1\nmanagement:\n  endpoints:\n    jmx:\n      exposure:\n        include: \"*\"\n    web:\n      exposure:\n        include: health,info,circuitbreakers,metrics,ratelimiters,bulkheads,retries,prometheus,logfile,redis\n        exclude: env,heapdump,threaddump,mappings\n  endpoint:\n    health:\n      show-details: always\n  health:\n    circuitbreakers:\n      enabled: true\n  otlp:\n    tracing:\n      endpoint: http://127.0.0.1:4318/v1/traces\n    metrics:\n      export:\n        url: http://127.0.0.1:4318/v1/metrics\n  metrics:\n    tags:\n      application: ${spring.application.name}\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n    propagation:\n      type:\n        - W3C\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.binlog.producer.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', 'b54e09472fe057f7ef4fccb64831a431', '2026-08-03 00:20:54', '2026-08-03 00:20:54', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (81, 15189, 'gateway-route.json', 'GATEWAY_GROUP', '', '[ {\n  \"id\" : \"iwindplus-mgt\",\n  \"uri\" : \"lb://iwindplus-mgt\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/mgt/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"管理服务\"\n  },\n  \"order\" : \"1\"\n}, {\n  \"id\" : \"iwindplus-log\",\n  \"uri\" : \"lb://iwindplus-log\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/log/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"日志服务\"\n  },\n  \"order\" : \"2\"\n}, {\n  \"id\" : \"iwindplus-auth\",\n  \"uri\" : \"lb://iwindplus-auth\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/api/auth/**\"\n    }\n  } ],\n  \"filters\" : [ {\n    \"name\" : \"StripPrefix\",\n    \"args\" : {\n      \"parts\" : \"2\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"认证服务\"\n  },\n  \"order\" : \"3\"\n}, {\n  \"id\" : \"iwindplus-im\",\n  \"uri\" : \"lb://iwindplus-im\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/im/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"即时通讯服务\"\n  },\n  \"order\" : \"4\"\n}, {\n  \"id\" : \"iwindplus-im-ws\",\n  \"uri\" : \"lb:ws://iwindplus-im-ws\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/imWs/**\"\n    }\n  } ],\n  \"filters\" : [ {\n    \"name\" : \"StripPrefix\",\n    \"args\" : {\n      \"parts\" : \"2\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"即时通讯websocket服务\"\n  },\n  \"order\" : \"5\"\n}, {\n  \"id\" : \"iwindplus-setup\",\n  \"uri\" : \"lb://iwindplus-setup\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/setup/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"配置服务\"\n  },\n  \"order\" : \"6\"\n}, {\n  \"id\" : \"iwindplus-flow\",\n  \"uri\" : \"lb://iwindplus-flow\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/flow/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"流程服务\"\n  },\n  \"order\" : \"7\"\n}, {\n  \"id\" : \"iwindplus-dtx\",\n  \"uri\" : \"lb://iwindplus-dtx\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/dtx/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"全局事务服务\"\n  },\n  \"order\" : \"8\"\n} ]', 'e890224e0ff6dd0fe5a27efcc6c77604', '2026-08-03 16:11:20', '2026-08-03 16:11:20', NULL, '172.20.10.11', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"json\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (69, 15191, 'messages_en_US.properties', 'I18N_GROUP', '', 'ok=Success\nmethod_not_allowed=Method Not Allowed\nparam_miss=Parameter ({0}) is missing\nparam_error=Parameter Error\nbad_request=Bad Request\nnot_found=Please check if the request path or type is correct\nunauthorized=Unauthorized\nconversion_not_supported=Conversion not supported\nunsupported_media_type=Unsupported Media Type\nnot_acceptable=Not Acceptable\nnot_writable=Not writable\nillegal_request=Illegal request, may be forged\naccount_locked=Account locked\naccount_disabled=Account disabled\nrequest_timeout=Request timeout\nrpc_error=RPC call exception\ngrant_type_not_empty=Grant type required\nunsupported_grant_type=Unsupported grant type\nunsupported_response_type=Unsupported response type\nsystem_busy=System busy, please try again later\ninvalid_account=Invalid account\ninvalid_credentials=Invalid credentials\ninvalid_access_token=Invalid access token\ninvalid_client=Invalid client\nunauthorized_client=Unauthorized client\ninvalid_grant=Invalid grant\ninvalid_refresh_token=Invalid refresh token\ninvalid_scope=Invalid scope\ninvalid_token=Invalid token\ninvalid_code=Invalid code\naccess_token_expired=Access token expired\naccess_token_format_error=Access token format error\nrefresh_token_expired=Refresh token expired\nrefresh_token_not_empty=Refresh token required\nscene.notEmpty=Scene value required\nmobile_not_exist=Mobile does not exist\nskey_not_exist=Binding key does not exist\ndata_not_exist=Data does not exist\naccount_not_exist=Account does not exist\npassword_error=Password error\ninvalid_account_or_client=Invalid account or client\nscope.userProfile=Get your nickname, avatar, etc\nid.notEmpty=ID required\njob_num_exist=Job number already exists\ninte