INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (3, 15605, 'iwindplus-mgt-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9001\n  shutdown: graceful\n  servlet:\n    application-display-name: 管理服务\n    encoding:\n      force: true\n      force-request: true\n      force-response: true\n  undertow:\n    threads:\n      io: 16\n      worker: 256\n    buffer-size: 1024\n    direct-buffers: true\ncross:\n  # 是否开启跨域\n  enabled: false\nfilter:\n  xss:\n    # 是否开启xss过滤器，防止攻击\n    enabled: true\n    # 是否启用跳过.\n    enabled-skip: true\n    # 忽略的API\n    ignored-api:\n      - /i18nProject/save\n      - /i18nProject/edit\n  request:\n    # 是否开启请求过滤器\n    enabled: true\n  # 过滤器加解密使用\n  crypto:\n    # 算法\n    algorithm: AES\n    # 公钥\n    # publicKey:\n    # 私钥\n    # privateKey:\n    # 密钥\n    # key:\n    # 初始化向量\n    # iv:\nhttp:\n  client:\n    api-protection:\n      # 是否开启API防护\n      enabled: true\n      enabled-remote: false\n      access-key: 555cb03355e1da059debe72b3e318c2c\n      secret-key: cd2o99YOb7hvx7enMk05YzmUSRXusGer\nglobal:\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\nresponse:\n  body:\n    enabled: true\n    crypto:\n      # 是否开启加密功能，默认关闭\n      enabled: false\n      # 算法\n      algorithm: RSA\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\njackson:\n  # 是否开启自定义jackson配置\n  enabled: true\n  sensitive:\n    # 是否开启敏感数据脱敏，响应接口结果时用\n    enabled: false\nvalidator:\n  # 是否开启参数校验\n  enabled: true\n  # 是否快速失败返回模式\n  fail-fast: true\nkey:\n  generator:\n    # 是否开启唯一key\n    enabled: true\n    # key是否开启加密\n    enabled-crypto: true\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nswagger:\n  server-api:\n    # 是否启用API注册\n    enabled: true\n    # 最大重试次数\n    maxRetry: 5\n    # 重试间隔时间（单位：秒）\n    retryInterval: 3\nasync-cmd:\n  # 是否开启异步命令\n  enabled: true\n  # 是否开启成功后删除数据\n  enabledSuccessDelete: false\n  # 是否开启成功后真实删除数据\n  enabledSuccessRealDelete: false\n  # 是否开启job\n  job:\n    enabled: true\n  web:\n    # 接口路径\n    path: admin/mgt/asyncCmd\n\nmgt:\n  ws:\n    # 是否开启ws推送\n    enabled: true\n  mail:\n    # 邮件模板编码\n    tpl-code: c3f67fd355dd6098156053f68285ba3e\n  sms:\n    # 短信模板编码\n    tpl-code: c3f67fd354dd6098154053f68285ba35\n  oss:\n    # 对象存储模板编码\n    tpl-code: c3f67fd355dd6098156053f68385ba34\nfeign:\n  request:\n    # 是否开启请求拦截器，传递请求头信息\n    enabled: true\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\n  sentinel:\n    enabled: true\nloadbalancer:\n  nacos:\n    # 是否开启nacos负载均衡，请求头设置version，支持灰度\n    enabled: true\n  custom:\n    # 是否开启自定义负载均衡，请求头设置version，支持灰度\n    enabled: false\n# 全局默认熔断策略\nresilience4j:\n  circuitbreaker:\n    configs:\n      default:\n        # 失败率阈值，达到50%触发熔断\n        failureRateThreshold: 50\n        # 慢调用率阈值\n        slowCallRateThreshold: 80\n        # 慢调用时间阈值（毫秒）\n        slowCallDurationThreshold: 1000\n        # 熔断器开启持续时间（秒）\n        waitDurationInOpenState: 10s\n        # 允许半开状态的最大调用数\n        permittedNumberOfCallsInHalfOpenState: 3\n        # 滑动窗口大小\n        slidingWindowSize: 10\n        # 最小调用次数才计算失败率\n        minimumNumberOfCalls: 5\n        # 自动从打开状态过渡到半开状态\n        automaticTransitionFromOpenToHalfOpenEnabled: true\n        # 仅以下异常计入失败\n        record-exceptions:\n          - java.io.IOException\n          - java.util.concurrent.TimeoutException\n    # 留空即可，全部走 default\n    instances: {}\n  timelimiter:\n    configs:\n      default:\n        # 单次调用硬超时 3 s（覆盖 Feign 默认 1 s）\n        timeout-duration: 3s\n  # 重试配置（可选）\n  retry:\n    configs:\n      default:\n        # 含首次，共 3 次\n        max-attempts: 3\n        wait-duration: 500ms\n        enable-exponential-backoff: true\n        exponential-backoff-multiplier: 1.5\n  # 限流配置（可选）\n  ratelimiter:\n    configs:\n      default:\n        limit-for-period: 10\n        limit-refresh-period: 1s\n        timeout-duration: 1000\n  # 隔离配置（可选）\n  bulkhead:\n    configs:\n      default:\n        maxConcurrentCalls: 10\n        maxWaitDuration: 0\ndynamictp:\n  enabled: true\n  enabledCollect: true\n  enabledBanner: true\n  collectorTypes: micrometer\n  monitorInterval: 5\n  platforms:\n    - platform: lark\n      platformId: 1\n      urlKey: e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n      receivers: test1,test2\n  globalExecutorProps:\n    rejectedHandlerType: CallerRunsPolicy\n    queueType: VariableLinkedBlockingQueue\n    waitForTasksToCompleteOnShutdown: true\n    awaitTerminationSeconds: 3\n    taskWrapperNames: [ \"micrometer\", \"ttl\", \"mdc\" ]\n    queueTimeout: 300\n    runTimeout: 300\n    notifyEnabled: true\n    notifyItems:\n      - type: change\n        silencePeriod: 120\n      - type: capacity\n        threshold: 80\n        count: 2\n        period: 30\n        silencePeriod: 0\n      - type: liveness\n        threshold: 80\n        count: 3\n        period: 30\n        silencePeriod: 0\n      - type: reject\n        count: 1\n        period: 30\n        silencePeriod: 0\n      - type: run_timeout\n        count: 20\n        period: 30\n        silencePeriod: 30\n      - type: queue_timeout\n        count: 5\n        period: 30\n        silencePeriod: 0\n  executors:\n    - threadPoolName: idempotentTaskScheduler\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      threadNamePrefix: idempotentTask\n      platformIds: [ 1 ]\n      runTimeout: 5000\n    - threadPoolName: asyncTaskExecutor\n      threadPoolAliasName: 异步任务线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: asyncTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nTaskExecutor\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      threadNamePrefix: i18nTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientTaskExecutor\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: httpClientTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: asyncCmdTaskExecutor\n      threadPoolAliasName: 异步命令线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: asyncCmdTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: asyncCmdSubTaskExecutor\n      threadPoolAliasName: 异步命令子任务线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: asyncCmdSubTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerTaskExecutor\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: kafkaListerTask\n      runTimeout: 0\n      queueTimeout: 0\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaLagTaskScheduler\n      threadPoolAliasName: kafka消息堆积调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      threadNamePrefix: kafkaLagTask\n      platformIds: [ 1 ]\n      runTimeout: 5000\n    - threadPoolName: disruptorTaskExecutor\n      threadPoolAliasName: disruptor线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: disruptorTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  cloud:\n    circuitbreaker:\n      resilience4j:\n        enabled: true\n    openfeign:\n      circuitbreaker:\n        # 开启服务熔断\n        enabled: true\n        group:\n          enabled: true\n      micrometer:\n        enabled: true\n      compression:\n        request:\n          enabled: false\n        response:\n          enabled: false\n      httpclient:\n        hc5:\n          enabled: true\n          connection-request-timeout: 3\n          socket-timeout: 10\n          pool-reuse-policy: fifo\n          pool-concurrency-policy: STRICT\n        # 默认连接超时时间：2000毫秒\n        connection-timeout: 5000\n        # 连接池管理定时器执行频率：默认 3000（单位：毫秒）\n        connection-timer-repeat: 5000\n        # 连接池最大连接数，默认200\n        max-connections: 500\n        # 每一个IP最大占用多少连接 默认 50\n        max-connections-per-route: 200\n        # 连接池中存活时间，默认为5\n        time-to-live: 10\n        time-to-live-unit: minutes\n        ok-http:\n          read-timeout: 10000\n      client:\n        config:\n          # default代表所有服务\n          default:\n            # 日志级别\n            loggerLevel: FULL\n            # feign客户端建立连接超时时间（单位：毫秒）\n            connect-timeout: 5000\n            # feign客户端建立连接后读取资源超时时间（单位：毫秒）\n            read-timeout: 10000\n      okhttp:\n        enabled: false\n  mvc:\n    path-match:\n      matching-strategy: ant_path_matcher\n  jmx:\n    enabled: true\n  messages:\n    basename: i18n/messages\n    fallback-to-system-locale: true\n    cache-duration: -1\n    # 是否开启远程消息源\n    enabled-remote: true\n    # nacos分组名称\n    group: I18N_GROUP\n  servlet:\n    multipart:\n      enabled: true\n      maxFileSize: 1GB\n      maxRequestSize: 10GB\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-mgt?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: root\n    # 数据库密码\n    password: njX@D*4ETsm3\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: 9&^7WR!#vnLs\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: false\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerTaskExecutor\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          enable-reactive: true\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-appCert-topic\n            group: iwindplus-appCert-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-apiWhiteList-topic\n            group: iwindplus-apiWhiteList-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-ipBlackList-topic\n            group: iwindplus-ipBlackList-group\n            # 是否自动创建\n            auto-create: true\nrocket:\n  multi:\n    enabled: true\n    default-cluster: default\n    clusters:\n      default:\n        nameServer: 127.0.0.1:9876\n        # 生产者配置\n        producer:\n          send-msg-timeout: 1000\n        # 消费者配置\n        consumer:\n          consume-message-batch-max-size: 10\n          # 绑定关系配置\n          bindings:\n            - topic: iwindplus-server-topic\n              group: iwindplus-server-group\n              tag: \"*\"\n            - topic: iwindplus-server1-topic\n              group: iwindplus-server-group\n              tag: \"*\"\nrabbit:\n  multi:\n    enabled: true\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        addresses: 127.0.0.1:5672\n        username: admin\n        password: EDH@T7JjfWFQ\n        virtual-host: /\n        connection-timeout: 5000\n        # 生产者配置\n        producer:\n          #这个配置是保证提供者确保消息推送到交换机中，不管成不成功，都会回调\n          publisher-confirm-type: correlated\n          #保证交换机能把消息推送到队列中\n          publisher-returns: true\n        # 消费者配置\n        consumer:\n          concurrency: 1\n          acknowledgeMode: MANUAL\n          enabledBatchListener: false\n          # 绑定关系配置\n          bindings:\n            - auto-create: true\n              routingKeys:\n                - iwindplus.server.demo\n              exchange:\n                name: iwindplus.server.demo\n                type: topic\n              queue:\n                name: iwindplus.server.demo\n                durable: true\n                arguments:\n                  x-queue-mode: lazy\n              group: iwindplus.server.demo\n            - auto-create: true\n              routingKeys:\n                - iwindplus.server.demo.batch\n              exchange:\n                name: iwindplus.server.demo.batch\n                type: topic\n              queue:\n                name: iwindplus.server.demo.batch\n                durable: true\n                arguments:\n                  x-queue-mode: lazy\n              group: iwindplus.server.demo.batch\nseata:\n  enabled: true\n  enable-auto-data-source-proxy: true\n  data-source-proxy-mode: XA\n  application-id: ${spring.application.name}\n  # 事务分组名称，要和服务端对应\n  tx-service-group: iwindplus_tx_group\n  service:\n    vgroup-mapping:\n      # key是事务分组名称 value要和服务端的机房名称保持一致\n      iwindplus_tx_group: default\n    grouplist:\n      default: 127.0.0.1:8091\n    disable-global-transaction: fals