d-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerTaskExecutor\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-loginLog-topic\n            group: iwindplus-loginLog-group\n            # 是否自动创建\n            auto-create: true\nlogging:\n  level:\n    root: INFO\n  console:\n    enabled: true\n    enabled-async: true\n  logstash:\n    enabled: true\n    enabled-async: true\n    address: 127.0.0.1:4560\n  config: classpath:logback-spring.xml\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 算法\n      algorithm: AES\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: 8W9QPBbekJdpE1mCdqRmkfyD5rJGqxiw\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n    stack:\n      max-length: -1\n      max-frames: -1\nmanagement:\n  endpoints:\n    jmx:\n      exposure:\n        include: \"*\"\n    web:\n      exposure:\n        include: health,info,circuitbreakers,metrics,ratelimiters,bulkheads,retries,prometheus,logfile,redis\n        exclude: env,heapdump,threaddump,mappings\n  endpoint:\n    health:\n      show-details: always\n  health:\n    circuitbreakers:\n      enabled: true\n  otlp:\n    tracing:\n      endpoint: http://127.0.0.1:4318/v1/traces\n    metrics:\n      export:\n        url: http://127.0.0.1:4318/v1/metrics\n  metrics:\n    tags:\n      application: ${spring.application.name}\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n    propagation:\n      type:\n        - W3C\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.auth.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '93ffe389f740a83fce22ac49b7a20c79', '2026-08-23 14:26:31', '2026-08-23 14:26:31', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (21, 16539, 'iwindplus-log-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9003\n  shutdown: graceful\n  servlet:\n    application-display-name: 日志服务\n    encoding:\n      force: true\n      force-request: true\n      force-response: true\n  undertow:\n    threads:\n      io: 16\n      worker: 256\n    buffer-size: 1024\n    direct-buffers: true\ncross:\n  # 是否开启跨域\n  enabled: false\nfilter:\n  xss:\n    # 是否开启xss过滤器，防止攻击\n    enabled: true\n  request:\n    # 是否开启请求过滤器\n    enabled: true\n  # 过滤器加解密使用\n  crypto:\n    # 算法\n    algorithm: AES\n    # 公钥\n    # publicKey:\n    # 私钥\n    # privateKey:\n    # 密钥\n    # key:\n    # 初始化向量\n    # iv:\nhttp:\n  client:\n    api-protection:\n      # 是否开启API防护\n      enabled: true\n      enabled-remote: false\n      access-key: ${httpClient-apiProtection-access-key}\n      secret-key: ${httpClient-apiProtection-secret-key}\nglobal:\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\nresponse:\n  body:\n    enabled: true\n    crypto:\n      # 是否开启加密功能，默认关闭\n      enabled: false\n      # 算法\n      algorithm: RSA\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\njackson:\n  # 是否开启自定义jackson配置\n  enabled: true\n  sensitive:\n    # 是否开启敏感数据脱敏，响应接口结果时用\n    enabled: false\nvalidator:\n  # 是否开启参数校验\n  enabled: true\n  # 是否快速失败返回模式\n  fail-fast: true\nkey:\n  generator:\n    # 是否开启唯一key\n    enabled: true\n    # key是否开启加密\n    enabled-crypto: true\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nfeign:\n  request:\n    # 是否开启请求拦截器，传递请求头信息\n    enabled: true\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\n  sentinel:\n    enabled: true\nloadbalancer:\n  nacos:\n    # 是否开启nacos负载均衡，请求头设置version，支持灰度\n    enabled: true\n  custom:\n    # 是否开启自定义负载均衡，请求头设置version，支持灰度\n    enabled: false\n# 全局默认熔断策略\nresilience4j:\n  circuitbreaker:\n    configs:\n      default:\n        # 失败率阈值，达到50%触发熔断\n        failureRateThreshold: 50\n        # 慢调用率阈值\n        slowCallRateThreshold: 80\n        # 慢调用时间阈值（毫秒）\n        slowCallDurationThreshold: 1000\n        # 熔断器开启持续时间（秒）\n        waitDurationInOpenState: 10s\n        # 允许半开状态的最大调用数\n        permittedNumberOfCallsInHalfOpenState: 3\n        # 滑动窗口大小\n        slidingWindowSize: 10\n        # 最小调用次数才计算失败率\n        minimumNumberOfCalls: 5\n        # 自动从打开状态过渡到半开状态\n        automaticTransitionFromOpenToHalfOpenEnabled: true\n        # 仅以下异常计入失败\n        record-exceptions:\n          - java.io.IOException\n          - java.util.concurrent.TimeoutException\n    # 留空即可，全部走 default\n    instances: {}\n  timelimiter:\n    configs:\n      default:\n        # 单次调用硬超时 3 s（覆盖 Feign 默认 1 s）\n        timeout-duration: 3s\n  # 重试配置（可选）\n  retry:\n    configs:\n      default:\n        # 含首次，共 3 次\n        max-attempts: 3\n        wait-duration: 500ms\n        enable-exponential-backoff: true\n        exponential-backoff-multiplier: 1.5\n  # 限流配置（可选）\n  ratelimiter:\n    configs:\n      default:\n        limit-for-period: 10\n        limit-refresh-period: 1s\n        timeout-duration: 1000\n  # 隔离配置（可选）\n  bulkhead:\n    configs:\n      default:\n        maxConcurrentCalls: 10\n        maxWaitDuration: 0\ndynamictp:\n  enabled: true\n  enabledCollect: true\n  enabledBanner: true\n  collectorTypes: micrometer\n  monitorInterval: 5\n  platforms:\n    - platform: lark\n      platformId: 1\n      urlKey: e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${dynamictp-lark-secret}\n      receivers: test1,test2\n  globalExecutorProps:\n    rejectedHandlerType: CallerRunsPolicy\n    queueType: VariableLinkedBlockingQueue\n    waitForTasksToCompleteOnShutdown: true\n    awaitTerminationSeconds: 3\n    taskWrapperNames: [ \"micrometer\", \"ttl\", \"mdc\" ]\n    queueTimeout: 300\n    runTimeout: 300\n    notifyEnabled: true\n    notifyItems:\n      - type: change\n        silencePeriod: 120\n      - type: capacity\n        threshold: 80\n        count: 2\n        period: 30\n        silencePeriod: 0\n      - type: liveness\n        threshold: 80\n        count: 3\n        period: 30\n        silencePeriod: 0\n      - type: reject\n        count: 1\n        period: 30\n        silencePeriod: 0\n      - type: run_timeout\n        count: 20\n        period: 30\n        silencePeriod: 30\n      - type: queue_timeout\n        count: 5\n        period: 30\n        silencePeriod: 0\n  executors:\n    - threadPoolName: idempotentTaskScheduler\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      threadNamePrefix: idempotentTask\n      platformIds: [ 1 ]\n      runTimeout: 5000\n    - threadPoolName: asyncTaskExecutor\n      threadPoolAliasName: 异步任务线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: asyncTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nTaskExecutor\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      threadNamePrefix: i18nTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientTaskExecutor\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: httpClientTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerTaskExecutor\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: kafkaListerTask\n      queueTimeout: 0\n      runTimeout: 0\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaLagTaskScheduler\n      threadPoolAliasName: kafka消息堆积调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      threadNamePrefix: kafkaLagTask\n      platformIds: [ 1 ]\n      runTimeout: 5000\n    - threadPoolName: disruptorTaskExecutor\n      threadPoolAliasName: disruptor线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: disruptorTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  elasticsearch:\n    uris: http://127.0.0.1:9200\n    username: elastic\n    password: zaq12wsx\n    connection-timeout: 5s\n    socket-timeout: 30s\n  cloud:\n    circuitbreaker:\n      resilience4j:\n        enabled: true\n    openfeign:\n      circuitbreaker:\n        # 开启服务熔断\n        enabled: true\n        group:\n          enabled: true\n      micrometer:\n        enabled: true\n      compression:\n        request:\n          enabled: false\n        response:\n          enabled: false\n      httpclient:\n        hc5:\n          enabled: true\n          connection-request-timeout: 3\n          socket-timeout: 10\n          pool-reuse-policy: fifo\n          pool-concurrency-policy: STRICT\n        # 默认连接超时时间：2000毫秒\n        connection-timeout: 5000\n        # 连接池管理定时器执行频率：默认 3000（单位：毫秒）\n        connection-timer-repeat: 5000\n        # 连接池最大连接数，默认200\n        max-connections: 500\n        # 每一个IP最大占用多少连接 默认 50\n        max-connections-per-route: 200\n        # 连接池中存活时间，默认为5\n        time-to-live: 10\n        time-to-live-unit: minutes\n        ok-http:\n          read-timeout: 10000\n      client:\n        config:\n          # default代表所有服务\n          default:\n            # 日志级别\n            loggerLevel: FULL\n            # feign客户端建立连接超时时间（单位：毫秒）\n            connect-timeout: 5000\n            # feign客户端建立连接后读取资源超时时间（单位：毫秒）\n            read-timeout: 10000\n      okhttp:\n        enabled: false\n  mvc:\n    path-match:\n      matching-strategy: ant_path_matcher\n  jmx:\n    enabled: true\n  messages:\n    basename: i18n/messages\n    fallback-to-system-locale: true\n    cache-duration: -1\n    # 是否开启远程消息源\n    enabled-remote: true\n    # nacos分组名称\n    group: I18N_GROUP\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: ${redis-password}\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: false\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerTaskExecutor\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          # 是否异步提交（并发情况）\n          enable-async-acks: true\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n          # 消息堆积量最大值（该参数和overloadLagThreshold判断是否需要扩容）\n          maxLag: 5\n          # 消息堆积量最小值（该参数和idleLagThreshold判断是否需要缩容）\n          minLag: 2\n          # 连续高lag阈值（该参数和maxLag判断是否需要扩容）\n          overloadLagThreshold: 5\n          # 连续低lag阈值（该参数和minLag判断是否需要缩容）\n          idleLagThreshold: 5\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-gatewayLog-topic\n            group: iwindplus-gatewayLog-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-loginLog-topic\n            group: iwindplus-loginLog-group\n            # 是否自动创建\n            auto-create: true\ndisruptor:\n  multi:\n    # 是否开启\n    enabled: true\n    configs:\n      # 对应kafka group\n      iwindplus-gatewayLog-group:\n        # 是否启用监控观察\n        enabled-observation: true\n        # 环形缓冲区大小\n        ring-buffer-size: 65536\n        # 生产者类型\n        producer-type: SINGLE\n        # 等待策略\n        wait-strategy: YIELDING\n        # 等待超时时间\n        timeout: 10\n        # 阻塞等待超时单位\n        time-unit: MILLISECONDS\n        # work线程池名称\n        thread-pool-name: disruptorTaskExecutor\n        # 恢复比例\n        resume-threshold: 0.5\n        # 暂停比例\n        pause-threshold: 0.1\n      iwindplus-loginLog-group:\n        # 是否启用监控观察\n        enabled-observation: true\n        # 环形缓冲区大小\n        ring-buffer-size: 65536\n        # 生产者类型\n        producer-type: SINGLE\n        # 等待策略\n        wait-strategy: YIELDING\n        # 等待超时时间\n        timeout: 10\n        # 阻塞等待超时单位\n        time-unit: MILLISECONDS\n        # work线程池名称\n        thread-pool-name: disruptorTaskExecutor\n        # 恢复比例\n        resume-threshold: 0.5\n        # 暂停比例\n        pause-threshold: 0.1\n# 地址服务配置\naddress:\n  # 是否启用地址服务\n  enabled: true\n  # 提供商配置列表\n  providers:\n    # 百度地图\n    baidu:\n      enabled: true\n      priority: 1\n      api-key: FFdlqXfexz0JOLmeTjhQqbOKPlteJLNJ\n      secret-key: ${address-baidu-secret-key}\n    # 高德地图\n    gaode:\n      enabled: true\n      priority: 2\n      api-key: 67e33f0347b5fa1d5d01977fd603414a\n      secret-key: ${address-gaode-secret-key}\n    # 腾讯地图\n    tencent:\n      enabled: true\n      priority: 3\n      api-key: GJMBZ-FCDWN-AFWFA-SP6NA-2RGVV-SCFN2\n      secret-key: ${address-tencent-secret-key}\n    # 138ip\n    ip138:\n      enabled: true\n      priority: 4\n      secret-key: ${address-138ip-secret-key}\n    # 太平洋网络（免费）\n    pconline:\n      enabled: true\n      priority: 5\nxxl-job:\n  enabled: true\n  admin:\n    addresses: http://127.0.0.1:9880/xxl-job-admin\n    access-token: ${xxl-job-access-token}\n  executor:\n    log-path: logs/job\n    log-retention-days: 30\n    app-name: ${spring.application.name}\n    ip: host.docker.internal\nlogging:\n  level:\n    root: INFO\n  console:\n    enabled: true\n    enabled-async: true\n  logstash:\n    enabled: true\n    enabled-async: true\n    address: 127.0.0.1:4560\n  config: classpath:logback-spring.xml\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nmanagement:\n  endpoints:\n    jmx:\n      exposure:\n        include: \"*\"\n    web:\n      exposure:\n        include: health,info,circuitbreakers,metrics,ratelimiters,bulkheads,retries,prometheus,logfile,redis\n        exclude: env,heapdump,threaddump,mappings\n  endpoint:\n    health:\n      show-details: always\n  health:\n    circuitbreakers:\n      enabled: true\n    elasticsearch:\n      enabled: false\n  otlp:\n    tracing:\n      endpoint: http://127.0.0.1:4318/v1/traces\n    metrics:\n      export:\n        url: http://127.0.0.1:4318/v1/metrics\n  metrics:\n    tags:\n      application: ${spring.application.name}\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n    propagation:\n      type:\n        - W3C\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.log.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '93f55cf8d7cf32ee4bf4ad0b090b7b90', '2026-08-23 14:26:54', '2026-08-23 14:26:54', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (23, 16541, 'iwindplus-im-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9004\n  shutdown: graceful\n  servlet:\n    application-display-name: 即时通讯服务\n    encoding:\n      force: true\n      force-request: true\n      force-response: true\n  undertow:\n    threads:\n      io: 16\n      worker: 256\n    buffer-size: 1024\n    direct-buffers: true\ncross:\n  # 是否开启跨域\n  enabled: false\nfilter:\n  xss:\n    # 是否开启xss过滤器，防止攻击\n    enabled: true\n  request:\n    # 是否开启请求过滤器\n    enabled: true\n  # 过滤器加解密使用\n  crypto:\n    # 算法\n    algorithm: AES\n    # 公钥\n    # publicKey:\n    # 私钥\n    # privateKey:\n    # 密钥\n    # key:\n    # 初始化向量\n    # iv:\nhttp:\n  client:\n    api-protection:\n      # 是否开启API防护\n      enabled: true\n      enabled-remote: false\n      access-key: 555cb03355e1da059debe72b3e318c2c\n      secret-key: cd2o99YOb7hvx7enMk05YzmUSRXusGer\nglobal:\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\nresponse:\n  body:\n    enabled: true\n    crypto:\n      # 是否开启加密功能，默认关闭\n      enabled: false\n      # 算法\n      algorithm: RSA\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\njackson:\n  # 是否开启自定义jackson配置\n  enabled: true\n  sensitive:\n    # 是否开启敏感数据脱敏，响应接口结果时用\n    enabled: false\nim:\n  # 是否启用远程token校验\n  enabled-remote-token: false\n  # 聊天群扫码加入地址\n  chatGroupScanUrl: https://www.iwindplus.com/im/joinChatGroup\n  mail:\n    # 邮件模板编码\n    tpl-code: c3f67fd355dd6098156053f68285ba3e\n  sms:\n    # 短信配置编码\n    code: 6856e64cc228215d44c1a351454a8cc5\n    # 短信模板编码\n    tpl-code: c3f67fd354dd6098154053f68285ba35\n  oss:\n    # 对象存储模板编码\n    tpl-code: c3f67fd355dd6098156053f68385ba35\nvalidator:\n  # 是否开启参数校验\n  enabled: true\n  # 是否快速失败返回模式\n  fail-fast: true\nkey:\n  generator:\n    # 是否开启唯一key\n    enabled: true\n    # key是否开启加密\n    enabled-crypto: true\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nfeign:\n  request:\n    # 是否开启请求拦截器，传递请求头信息\n    enabled: true\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\n  sentinel:\n    enabled: true\nloadbalancer:\n  nacos:\n    # 是否开启nacos负载均衡，请求头设置version，支持灰度\n    enabled: true\n  custom:\n    # 是否开启自定义负载均衡，请求头设置version，支持灰度\n    enabled: false\nmongo:\n  field:\n    fill:\n      # 是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: false\n# 全局默认熔断策略\nresilience4j:\n  circuitbreaker:\n    configs:\n      default:\n        # 失败率阈值，达到50%触发熔断\n        failureRateThreshold: 50\n        # 慢调用率阈值\n        slowCallRateThreshold: 80\n        # 慢调用时间阈值（毫秒）\n        slowCallDurationThreshold: 1000\n        # 熔断器开启持续时间（秒）\n        waitDurationInOpenState: 10s\n        # 允许半开状态的最大调用数\n        permittedNumberOfCallsInHalfOpenState: 3\n        # 滑动窗口大小\n        slidingWindowSize: 10\n        # 最小调用次数才计算失败率\n        minimumNumberOfCalls: 5\n        # 自动从打开状态过渡到半开状态\n        automaticTransitionFromOpenToHalfOpenEnabled: true\n        # 仅以下异常计入失败\n        record-exceptions:\n          - java.io.IOException\n          - java.util.concurrent.TimeoutException\n    # 留空即可，全部走 default\n    instances: {}\n  timelimiter:\n    configs:\n      default:\n        # 单次调用硬超时 3 s（覆盖 Feign 默认 1 s）\n        timeout-duration: 3s\n  # 重试配置（可选）\n  retry:\n    configs:\n      default:\n        # 含首次，共 3 次\n        max-attempts: 3\n        wait-duration: 500ms\n        enable-exponential-backoff: true\n        exponential-backoff-multiplier: 1.5\n  # 限流配置（可选）\n  ratelimiter:\n    configs:\n      default:\n        limit-for-period: 10\n        limit-refresh-period: 1s\n        timeout-duration: 1000\n  # 隔离配置（可选）\n  bulkhead:\n    configs:\n      default:\n        maxConcurrentCalls: 10\n        maxWaitDuration: 0\ndynamictp:\n  enabled: true\n  enabledCollect: true\n  enabledBanner: true\n  collectorTypes: micrometer\n  monitorInterval: 5\n  platforms:\n    - platform: lark\n      platformId: 1\n      urlKey: e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n      receivers: test1,test2\n  globalExecutorProps:\n    rejectedHandlerType: CallerRunsPolicy\n    queueType: VariableLinkedBlockingQueue\n    waitForTasksToCompleteOnShutdown: true\n    awaitTerminationSeconds: 3\n    taskWrapperNames: [ \"micrometer\", \"ttl\", \"mdc\" ]\n    queueTimeout: 300\n    runTimeout: 300\n    notifyEnabled: true\n    notifyItems:\n      - type: change\n        silencePeriod: 120\n      - type: capacity\n        threshold: 80\n        count: 2\n        period: 30\n        silencePeriod: 0\n      - type: liveness\n        threshold: 80\n        count: 3\n        period: 30\n        silencePeriod: 0\n      - type: reject\n        count: 1\n        period: 30\n        silencePeriod: 0\n      - type: run_timeout\n        count: 20\n        period: 30\n        silencePeriod: 30\n      - type: queue_timeout\n        count: 5\n        period: 30\n        silencePeriod: 0\n  executors:\n    - threadPoolName: idempotentTaskScheduler\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      threadNamePrefix: idempotentTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: asyncTaskExecutor\n      threadPoolAliasName: 异步任务线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: asyncTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nTaskExecutor\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      threadNamePrefix: i18nTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientTaskExecutor\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: httpClientTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  cloud:\n    circuitbreaker:\n      resilience4j:\n        enabled: true\n    openfeign:\n      circuitbreaker:\n        # 开启服务熔断\n        enabled: true\n        group:\n          enabled: true\n      micrometer:\n        enabled: true\n      compression:\n        request:\n          enabled: false\n        response:\n          enabled: false\n      httpclient:\n        hc5:\n          enabled: true\n          connection-request-timeout: 3\n          socket-timeout: 10\n          pool-reuse-policy: fifo\n          pool-concurrency-policy: STRICT\n        # 默认连接超时时间：2000毫秒\n        connection-timeout: 5000\n        # 连接池管理定时器执行频率：默认 3000（单位：毫秒）\n        connection-timer-repeat: 5000\n        # 连接池最大连接数，默认200\n        max-connections: 500\n        # 每一个IP最大占用多少连接 默认 50\n        max-connections-per-route: 200\n        # 连接池中存活时间，默认为5\n        time-to-live: 10\n        time-to-live-unit: minutes\n        ok-http:\n          read-timeout: 10000\n      client:\n        config:\n          # default代表所有服务\n          default:\n            # 日志级别\n            loggerLevel: FULL\n            # feign客户端建立连接超时时间（单位：毫秒）\n            connect-timeout: 5000\n            # feign客户端建立连接后读取资源超时时间（单位：毫秒）\n            read-timeout: 10000\n      okhttp:\n        enabled: false\n  mvc:\n    path-match:\n      matching-strategy: ant_path_matcher\n  jmx:\n    enabled: true\n  messages:\n    basename: i18n/messages\n    fallback-to-system-locale: true\n    cache-duration: -1\n    # 是否开启远程消息源\n    enabled-remote: true\n    # nacos分组名称\n    group: I18N_GROUP\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-im?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: root\n    # 数据库密码\n    password: njX@D*4ETsm3\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: 9&^7WR!#vnLs\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\n  elasticsearch:\n    uris: http://127.0.0.1:9200\n    username: elastic\n    password: zaq12wsx\n    connection-timeout: 5s\n    socket-timeout: 30s\nwebsocket:\n  server:\n    # 是否开启websocket\n    enabled: true\n    # 是否开启debug\n    debug: true\n    # 是否使用队列发送消息\n    useQueueSend: true\n    # 是否使用队列解码消息\n    useQueueDecode: true\n    # 解码出现异常时，是否打印异常日志\n    logWhenDecodeError: true\n    # websocket服务名称\n    name: ${spring.application.name}-ws\n    #  websocket服务端口\n    port: 9326\n    # 心跳超时时间\n    heartbeat-timeout: 0\n  ssl:\n    # 密钥库存储路径\n    keyStore:\n    # 信任存储路径\n    trustStore:\n    # 密钥库密码\n    password:\n  cluster:\n    # 是否开启集群\n    enabled: true\n    # 发消息到组\n    group: true\n    # 发消息给指定业务ID\n    bs-id: true\n    #  发消息给指定用户\n    user: true\n    # 发送到指定ip\n    ip: true\n    # 发消息给指定通道\n    channel: true\n    # 发消息到所有连接\n    all: true\nseata:\n  enabled: true\n  enable-auto-data-source-proxy: true\n  data-source-proxy-mode: XA\n  application-id: ${spring.application.name}\n  # 事务分组名称，要和服务端对应\n  tx-service-group: iwindplus_tx_group\n  service:\n    vgroup-mapping:\n      # key是事务分组名称 value要和服务端的机房名称保持一致\n      iwindplus_tx_group: default\n    grouplist:\n      default: 127.0.0.1:8091\n    disable-global-transaction: false\nlogging:\n  level:\n    root: INFO\n  console:\n    enabled: true\n    enabled-async: true\n  logstash:\n    enabled: true\n    enabled-async: true\n    address: 127.0.0.1:4560\n  config: classpath:logback-spring.xml\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 算法\n      algorithm: AES\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: 8W9QPBbekJdpE1mCdqRmkfyD5rJGqxiw\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n    stack:\n      max-length: -1\n      max-frames: -1\nmanagement:\n  endpoints:\n    jmx:\n      exposure:\n        include: \"*\"\n    web:\n      exposure:\n        include: health,info,circuitbreakers,metrics,ratelimiters,bulkheads,retries,prometheus,logfile,redis\n        exclude: env,heapdump,threaddump,mappings\n  endpoint:\n    health:\n      show-details: always\n  health:\n    circuitbreakers:\n      enabled: true\n    elasticsearch:\n      enabled: false\n  otlp:\n    tracing:\n      endpoint: http://127.0.0.1:4318/v1/traces\n    metrics:\n      export:\n        url: http://127.0.0.1:4318/v1/metrics\n  metrics:\n    tags:\n      application: ${spring.application.name}\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n    propagation:\n      type:\n        - W3C\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.im.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '96a4cc08a6d298264c0b9157ff87344c', '2026-08-23 14:27:10', '2026-08-23 14:27:10', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (25, 16543, 'iwindplus-setup-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9006\n  shutdown: graceful\n  servlet:\n    application-display-name: 通用设置服务\n    encoding:\n      force: true\n      force-request: true\n      force-response: true\n  undertow:\n    threads:\n      io: 16\n      worker: 256\n    buffer-size: 1024\n    direct-buffers: true\ncross:\n  # 是否开启跨域\n  enabled: false\nfilter:\n  xss:\n    # 是否开启xss过滤器，防止攻击\n    enabled: true\n  request:\n    # 是否开启请求过滤器\n    enabled: true\n  # 过滤器加解密使用\n  crypto:\n    # 算法\n    algorithm: AES\n    # 公钥\n    # publicKey:\n    # 私钥\n    # privateKey:\n    # 密钥\n    # key:\n    # 初始化向量\n    # iv:\nhttp:\n  client:\n    # 是否启用每次请求观察（客户端自带的）\n    enabled-observation: true\n    # 是否启用每次请求观察（自定义）\n    enabled-observation-custom: false\n    api-protection:\n      # 是否开启API防护\n      enabled: true\n      enabled-remote: false\n      access-key: 555cb03355e1da059debe72b3e318c2c\n      secret-key: cd2o99YOb7hvx7enMk05YzmUSRXusGer\nglobal:\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\nresponse:\n  body:\n    enabled: true\n    crypto:\n      # 是否开启加密功能，默认关闭\n      enabled: false\n      # 算法\n      algorithm: RSA\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\njackson:\n  # 是否开启自定义jackson配置\n  enabled: true\n  sensitive:\n    # 是否开启敏感数据脱敏，响应接口结果时用\n    enabled: false\nvalidator:\n  # 是否开启参数校验\n  enabled: true\n  # 是否快速失败返回模式\n  fail-fast: true\nkey:\n  generator:\n    # 是否开启唯一key\n    enabled: true\n    # key是否开启加密\n    enabled-crypto: true\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nfeign:\n  request:\n    # 是否开启请求拦截器，传递请求头信息\n    enabled: true\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\n  sentinel:\n    enabled: true\nloadbalancer:\n  nacos:\n    # 是否开启nacos负载均衡，请求头设置version，支持灰度\n    enabled: true\n  custom:\n    # 是否开启自定义负载均衡，请求头设置version，支持灰度\n    enabled: false\n# 全局默认熔断策略\nresilience4j:\n  circuitbreaker:\n    configs:\n      default:\n        # 失败率阈值，达到50%触发熔断\n        failureRateThreshold: 50\n        # 慢调用率阈值\n        slowCallRateThreshold: 80\n        # 慢调用时间阈值（毫秒）\n        slowCallDurationThreshold: 1000\n        # 熔断器开启持续时间（秒）\n        waitDurationInOpenState: 10s\n        # 允许半开状态的最大调用数\n        permittedNumberOfCallsInHalfOpenState: 3\n        # 滑动窗口大小\n        slidingWindowSize: 10\n        # 最小调用次数才计算失败率\n        minimumNumberOfCalls: 5\n        # 自动从打开状态过渡到半开状态\n        automaticTransitionFromOpenToHalfOpenEnabled: true\n        # 仅以下异常计入失败\n        record-exceptions:\n          - java.io.IOException\n          - java.util.concurrent.TimeoutException\n    # 留空即可，全部走 default\n    instances: {}\n  timelimiter:\n    configs:\n      default:\n        # 单次调用硬超时 3 s（覆盖 Feign 默认 1 s）\n        timeout-duration: 3s\n  # 重试配置（可选）\n  retry:\n    configs:\n      default:\n        # 含首次，共 3 次\n        max-attempts: 3\n        wait-duration: 500ms\n        enable-exponential-backoff: true\n        exponential-backoff-multiplier: 1.5\n  # 限流配置（可选）\n  ratelimiter:\n    configs:\n      default:\n        limit-for-period: 10\n        limit-refresh-period: 1s\n        timeout-duration: 1000\n  # 隔离配置（可选）\n  bulkhead:\n    configs:\n      default:\n        maxConcurrentCalls: 10\n        maxWaitDuration: 0\ndynamictp:\n  enabled: true\n  enabledCollect: true\n  enabledBanner: true\n  collectorTypes: micrometer\n  monitorInterval: 5\n  platforms:\n    - platform: lark\n      platformId: 1\n      urlKey: e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n      receivers: test1,test2\n  globalExecutorProps:\n    rejectedHandlerType: CallerRunsPolicy\n    queueType: VariableLinkedBlockingQueue\n    waitForTasksToCompleteOnShutdown: true\n    awaitTerminationSeconds: 3\n    taskWrapperNames: [ \"micrometer\", \"ttl\", \"mdc\" ]\n    queueTimeout: 300\n    runTimeout: 300\n    notifyEnabled: true\n    notifyItems:\n      - type: change\n        silencePeriod: 120\n      - type: capacity\n        threshold: 80\n        count: 2\n        period: 30\n        silencePeriod: 0\n      - type: liveness\n        threshold: 80\n        count: 3\n        period: 30\n        silencePeriod: 0\n      - type: reject\n        count: 1\n        period: 30\n        silencePeriod: 0\n      - type: run_timeout\n        count: 20\n        period: 30\n        silencePeriod: 30\n      - type: queue_timeout\n        count: 5\n        period: 30\n        silencePeriod: 0\n  executors:\n    - threadPoolName: idempotentTaskScheduler\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      threadNamePrefix: idempotentTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: asyncTaskExecutor\n      threadPoolAliasName: 异步任务线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: asyncTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nTaskExecutor\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      threadNamePrefix: i18nTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientTaskExecutor\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: httpClientTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: ossTaskExecutor\n      threadPoolAliasName: 对象存储线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: ossTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: smsTaskExecutor\n      threadPoolAliasName: 短信线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: smsTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  cloud:\n    circuitbreaker:\n      resilience4j:\n        enabled: true\n    openfeign:\n      circuitbreaker:\n        # 开启服务熔断\n        enabled: true\n        group:\n          enabled: true\n      micrometer:\n        enabled: true\n      compression:\n        request:\n          enabled: false\n        response:\n          enabled: false\n      httpclient:\n        hc5:\n          enabled: true\n          connection-request-timeout: 3\n          socket-timeout: 10\n          pool-reuse-policy: fifo\n          pool-concurrency-policy: STRICT\n        # 默认连接超时时间：2000毫秒\n        connection-timeout: 5000\n        # 连接池管理定时器执行频率：默认 3000（单位：毫秒）\n        connection-timer-repeat: 5000\n        # 连接池最大连接数，默认200\n        max-connections: 500\n        # 每一个IP最大占用多少连接 默认 50\n        max-connections-per-route: 200\n        # 连接池中存活时间，默认为5\n        time-to-live: 10\n        time-to-live-unit: minutes\n        ok-http:\n          read-timeout: 10000\n      client:\n        config:\n          # default代表所有服务\n          default:\n            # 日志级别\n            loggerLevel: FULL\n            # feign客户端建立连接超时时间（单位：毫秒）\n            connect-timeout: 5000\n            # feign客户端建立连接后读取资源超时时间（单位：毫秒）\n            read-timeout: 10000\n      okhttp:\n        enabled: false\n  mvc:\n    path-match:\n      matching-strategy: ant_path_matcher\n  jmx:\n    enabled: true\n  messages:\n    basename: i18n/messages\n    fallback-to-system-locale: true\n    cache-duration: -1\n    # 是否开启远程消息源\n    enabled-remote: true\n    # nacos分组名称\n    group: I18N_GROUP\n  servlet:\n    multipart:\n      enabled: true\n      maxFileSize: 1GB\n      maxRequestSize: 10GB\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-setup?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: root\n    # 数据库密码\n    password: njX@D*4ETsm3\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: 9&^7WR!#vnLs\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nseata:\n  enabled: true\n  enable-auto-data-source-proxy: true\n  data-source-proxy-mode: XA\n  application-id: ${spring.application.name}\n  # 事务分组名称，要和服务端对应\n  tx-service-group: iwindplus_tx_group\n  service:\n    vgroup-mapping:\n      # key是事务分组名称 value要和服务端的机房名称保持一致\n      iwindplus_tx_group: default\n    grouplist:\n      default: 127.0.0.1:8091\n    disable-global-transaction: false\nsms:\n  aliyun:\n    # 是否开启阿里云短信\n    enabled: true\n  qiniu:\n    # 是否开启七牛云短信\n    enabled: true\n  lingkai:\n    # 是否开启凌凯短信\n    enabled: true\n  mxtong:\n    # 是否开启麦讯通短信\n    enabled: true\noss:\n  minio:\n    # 是否开启minio\n    enabled: true\n  aliyun:\n    # 是否开启阿里云OSS\n    enabled: true\n  qiniu:\n    # 是否开启七牛云OSS\n    enabled: true\nvod:\n  aliyun:\n    # 是否开启阿里云VOD\n    enabled: true\nwechat:\n  ma:\n    # 是否开启微信小程序\n    enabled: true\n  mp:\n    # 是否开启微信公众号\n    enabled: true\nocr:\n  print-word:\n    # 是否开启打印文字\n    enabled: true\n    # 应用编码\n    app-code: 7462f566cd73490f94da4a51b70a51f1\n  xiangyun:\n    # 是否开启翔云\n    enabled: true\n    # 访问key\n    accessKey:\n    # 密钥\n    secretKey:\nlogging:\n  level:\n    root: INFO\n  console:\n    enabled: true\n    enabled-async: true\n  logstash:\n    enabled: true\n    enabled-async: true\n    address: 127.0.0.1:4560\n  config: classpath:logback-spring.xml\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 算法\n      algorithm: AES\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: 8W9QPBbekJdpE1mCdqRmkfyD5rJGqxiw\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n    stack:\n      max-length: -1\n      max-frames: -1\nmanagement:\n  endpoints:\n    jmx:\n      exposure:\n        include: \"*\"\n    web:\n      exposure:\n        include: health,info,circuitbreakers,metrics,ratelimiters,bulkheads,retries,prometheus,logfile,redis\n        exclude: env,heapdump,threaddump,mappings\n  endpoint:\n    health:\n      show-details: always\n  health:\n    circuitbreakers:\n      enabled: true\n  otlp:\n    tracing:\n      endpoint: http://127.0.0.1:4318/v1/traces\n    metrics:\n      export:\n        url: http://127.0.0.1:4318/v1/metrics\n  metrics:\n    tags:\n      application: ${spring.application.name}\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n    propagation:\n      type:\n        - W3C\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.setup.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', 'ba69c7eb5ffac53340074890ad45ca4c', '2026-08-23 14:27:30', '2026-08-23 14:27:30', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (27, 16545, 'iwindplus-flow-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9007\n  shutdown: graceful\n  servlet:\n    application-display-name: 流程服务\n    encoding:\n      force: true\n      force-request: true\n      force-response: true\n  undertow:\n    threads:\n      io: 16\n      worker: 256\n    buffer-size: 1024\n    direct-buffers: true\ncross:\n  # 是否开启跨域\n  enabled: false\nfilter:\n  xss:\n    # 是否开启xss过滤器，防止攻击\n    enabled: true\n  request:\n    # 是否开启请求过滤器\n    enabled: true\n  # 过滤器加解密使用\n  crypto:\n    # 算法\n    algorithm: AES\n    # 公钥\n    # publicKey:\n    # 私钥\n    # privateKey:\n    # 密钥\n    # key:\n    # 初始化向量\n    # iv:\nhttp:\n  client:\n    api-protection:\n      # 是否开启API防护\n      enabled: true\n      enabled-remote: false\n      access-key: 555cb03355e1da059debe72b3e318c2c\n      secret-key: cd2o99YOb7hvx7enMk05YzmUSRXusGer\nglobal:\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\nresponse:\n  body:\n    enabled: true\n    crypto:\n      # 是否开启加密功能，默认关闭\n      enabled: false\n      # 算法\n      algorithm: RSA\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\njackson:\n  # 是否开启自定义jackson配置\n  enabled: true\n  sensitive:\n    # 是否开启敏感数据脱敏，响应接口结果时用\n    enabled: false\nvalidator:\n  # 是否开启参数校验\n  enabled: true\n  # 是否快速失败返回模式\n  fail-fast: true\nkey:\n  generator:\n    # 是否开启唯一key\n    enabled: true\n    # key是否开启加密\n    enabled-crypto: true\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nswagger:\n  server-api:\n    # 是否启用API注册\n    enabled: true\n    # 最大重试次数\n    maxRetry: 5\n    # 重试间隔时间（单位：秒）\n    retryInterval: 3\nfeign:\n  request:\n    # 是否开启请求拦截器，传递请求头信息\n    enabled: true\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\n  sentinel:\n    enabled: true\nloadbalancer:\n  nacos:\n    # 是否开启nacos负载均衡，请求头设置version，支持灰度\n    enabled: true\n  custom:\n    # 是否开启自定义负载均衡，请求头设置version，支持灰度\n    enabled: false\n# 全局默认熔断策略\nresilience4j:\n  circuitbreaker:\n    configs:\n      default:\n        # 失败率阈值，达到50%触发熔断\n        failureRateThreshold: 50\n        # 慢调用率阈值\n        slowCallRateThreshold: 80\n        # 慢调用时间阈值（毫秒）\n        slowCallDurationThreshold: 1000\n        # 熔断器开启持续时间（秒）\n        waitDurationInOpenState: 10s\n        # 允许半开状态的最大调用数\n        permittedNumberOfCallsInHalfOpenState: 3\n        # 滑动窗口大小\n        slidingWindowSize: 10\n        # 最小调用次数才计算失败率\n        minimumNumberOfCalls: 5\n        # 自动从打开状态过渡到半开状态\n        automaticTransitionFromOpenToHalfOpenEnabled: true\n        # 仅以下异常计入失败\n        record-exceptions:\n          - java.io.IOException\n          - java.util.concurrent.TimeoutException\n    # 留空即可，全部走 default\n    instances: {}\n  timelimiter:\n    configs:\n      default:\n        # 单次调用硬超时 3 s（覆盖 Feign 默认 1 s）\n        timeout-duration: 3s\n  # 重试配置（可选）\n  retry:\n    configs:\n      default:\n        # 含首次，共 3 次\n        max-attempts: 3\n        wait-duration: 500ms\n        enable-exponential-backoff: true\n        exponential-backoff-multiplier: 1.5\n  # 限流配置（可选）\n  ratelimiter:\n    configs:\n      default:\n        limit-for-period: 10\n        limit-refresh-period: 1s\n        timeout-duration: 1000\n  # 隔离配置（可选）\n  bulkhead:\n    configs:\n      default:\n        maxConcurrentCalls: 10\n        maxWaitDuration: 0\ndynamictp:\n  enabled: true\n  enabledCollect: true\n  enabledBanner: true\n  collectorTypes: micrometer\n  monitorInterval: 5\n  platforms:\n    - platform: lark\n      platformId: 1\n      urlKey: e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n      receivers: test1,test2\n  globalExecutorProps:\n    rejectedHandlerType: CallerRunsPolicy\n    queueType: VariableLinkedBlockingQueue\n    waitForTasksToCompleteOnShutdown: true\n    awaitTerminationSeconds: 3\n    taskWrapperNames: [ \"micrometer\", \"ttl\", \"mdc\" ]\n    queueTimeout: 300\n    runTimeout: 300\n    notifyEnabled: true\n    notifyItems:\n      - type: change\n        silencePeriod: 120\n      - type: capacity\n        threshold: 80\n        count: 2\n        period: 30\n        silencePeriod: 0\n      - type: liveness\n        threshold: 80\n        count: 3\n        period: 30\n        silencePeriod: 0\n      - type: reject\n        count: 1\n        period: 30\n        silencePeriod: 0\n      - type: run_timeout\n        count: 20\n        period: 30\n        silencePeriod: 30\n      - type: queue_timeout\n        count: 5\n        period: 30\n        silencePeriod: 0\n  executors:\n    - threadPoolName: idempotentTaskScheduler\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      threadNamePrefix: idempotentTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: asyncTaskExecutor\n      threadPoolAliasName: 异步任务线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: asyncTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nTaskExecutor\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      threadNamePrefix: i18nTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientTaskExecutor\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: httpClientTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  cloud:\n    circuitbreaker:\n      resilience4j:\n        enabled: true\n    openfeign:\n      circuitbreaker:\n        # 开启服务熔断\n        enabled: true\n        group:\n          enabled: true\n      micrometer:\n        enabled: true\n      compression:\n        request:\n          enabled: false\n        response:\n          enabled: false\n      httpclient:\n        hc5:\n          enabled: true\n          connection-request-timeout: 3\n          socket-timeout: 10\n          pool-reuse-policy: fifo\n          pool-concurrency-policy: STRICT\n        # 默认连接超时时间：2000毫秒\n        connection-timeout: 5000\n        # 连接池管理定时器执行频率：默认 3000（单位：毫秒）\n        connection-timer-repeat: 5000\n        # 连接池最大连接数，默认200\n        max-connections: 500\n        # 每一个IP最大占用多少连接 默认 50\n        max-connections-per-route: 200\n        # 连接池中存活时间，默认为5\n        time-to-live: 10\n        time-to-live-unit: minutes\n        ok-http:\n          read-timeout: 10000\n      client:\n        config:\n          # default代表所有服务\n          default:\n            # 日志级别\n            loggerLevel: FULL\n            # feign客户端建立连接超时时间（单位：毫秒）\n            connect-timeout: 5000\n            # feign客户端建立连接后读取资源超时时间（单位：毫秒）\n            read-timeout: 10000\n      okhttp:\n        enabled: false\n  mvc:\n    path-match:\n      matching-strategy: ant_path_matcher\n  jmx:\n    enabled: true\n  messages:\n    basename: i18n/messages\n    fallback-to-system-locale: true\n    cache-duration: -1\n    # 是否开启远程消息源\n    enabled-remote: true\n    # nacos分组名称\n    group: I18N_GROUP\n  servlet:\n    multipart:\n      enabled: true\n      maxFileSize: 1GB\n      maxRequestSize: 10GB\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-flow?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: root\n    # 数据库密码\n    password: njX@D*4ETsm3\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: 9&^7WR!#vnLs\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nseata:\n  enabled: true\n  enable-auto-data-source-proxy: true\n  data-source-proxy-mode: XA\n  application-id: ${spring.application.name}\n  # 事务分组名称，要和服务端对应\n  tx-service-group: iwindplus_tx_group\n  service:\n    vgroup-mapping:\n      # key是事务分组名称 value要和服务端的机房名称保持一致\n      iwindplus_tx_group: default\n    grouplist:\n      default: 127.0.0.1:8091\n    disable-global-transaction: false\nxxl-job:\n  enabled: true\n  admin:\n    addresses: http://127.0.0.1:9880/xxl-job-admin\n    access-token: c61909bdde7b5cbeb27adeeff43ac55c\n  executor:\n    log-path: logs/job\n    log-retention-days: 30\n    app-name: ${spring.application.name}\n    ip: host.docker.internal\nlogging:\n  level:\n    root: INFO\n  console:\n    enabled: true\n    enabled-async: true\n  logstash:\n    enabled: true\n    enabled-async: true\n    address: 127.0.0.1:4560\n  config: classpath:logback-spring.xml\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 算法\n      algorithm: AES\n      # 公钥\n      # publicKey:\n      # 私钥\n      # privateKey:\n      # 密钥\n      # key:\n      # 初始化向量\n      # iv:\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: 8W9QPBbekJdpE1mCdqRmkfyD5rJGqxiw\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: 3XcRTx6zi3GqOgIAYZKhbb\n    stack:\n      max-length: -1\n      max-frames: -1\nmanagement:\n  endpoints:\n    jmx:\n      exposure:\n        include: \"*\"\n    web:\n      exposure:\n        include: health,info,circuitbreakers,metrics,ratelimiters,bulkheads,retries,prometheus,logfile,redis\n        exclude: env,heapdump,threaddump,mappings\n  endpoint:\n    health:\n      show-details: always\n  health:\n    circuitbreakers:\n      enabled: true\n  otlp:\n    tracing:\n      endpoint: http://127.0.0.1:4318/v1/traces\n    metrics:\n      export:\n        url: http://127.0.0.1:4318/v1/metrics\n  metrics:\n    